"""Round M: fresh SYNTHETIC DEVELOPMENT scenarios (author hypotheses, NOT expert-adjudicated).

Deliberately harder than Round J: scripted answers use everyday lay wording, never the knowledge
base's own phrases, so success requires real evidence extraction, not string recall. Unscripted
actions still get the simulator's artificial normal/negative default (a documented limitation).
Families probe discrimination (truth often NOT the first-listed obvious answer), paraphrase
stability (_A/_B pairs share meaning but not wording), ko/ja/mixed-language, symptom-only long-tail
(no diagnosis named), and OOD controls. Authored before any Round M reasoning edit. No blind module
is imported; nothing copies Blind v14-v18 wording. Development data: may be iterated against.
"""
from evaluation.cases import SyntheticCase


def m(n, text, truth, *, a=None, e=None, t=None, tags='', age=47, sex='female', scored=True):
    return SyntheticCase(case_id=f'RoundM_{n:03}', chief_complaint=text, ground_truth_diagnosis=truth,
        demographics={'age': age, 'sex': sex}, answers=a or {}, exam_results=e or {}, test_results=t or {},
        category=tags, scoring_expected=scored,
        notes='Fresh synthetic development; author hypothesis; not independently adjudicated.')


